package com.integral.forgottenrelics.registry;

import com.integral.forgottenrelics.ForgottenRelics;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.Identifier;
import net.minecraft.tags.TagKey;
import net.minecraft.world.damagesource.DamageType;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.item.Item;

/** Tags owned by the mod (JSON generated by tools/gen_assets.py). */
public final class FRTags {
    public static final TagKey<Item> PARADOX_REPAIR_MATERIALS = TagKey.create(Registries.ITEM,
            ForgottenRelics.id("paradox_repair_materials"));

    /** Thaumaturge's wand, staff and sceptre items: what TC4 called {@code ItemWandCasting}. */
    public static final TagKey<Item> WANDS = TagKey.create(Registries.ITEM, Identifier.fromNamespaceAndPath("thaumaturge", "wands"));

    /**
     * Original {@code SuperpositionHandler#isDamageTypeAbsolute}: out-of-world, starvation and the mod's own
     * true/soul/fate/oblivion damage. Relic defences never touch these.
     */
    public static final TagKey<DamageType> ABSOLUTE_DAMAGE = TagKey.create(Registries.DAMAGE_TYPE, ForgottenRelics.id("absolute"));

    /**
     * Original {@code EntityThaumcraftBoss || EntityDoppleganger} checks: bosses that relics must not grab, swap or
     * redirect damage to. Thaumaturge bosses, Botania's Gaia Guardian and {@code #c:bosses}.
     */
    public static final TagKey<EntityType<?>> RELIC_BOSSES = TagKey.create(Registries.ENTITY_TYPE, ForgottenRelics.id("relic_bosses"));

    private FRTags() {
    }
}
